<script setup lang="ts">
import { onLoad, onUnload } from "@dcloudio/uni-app";
import { ref } from "vue";
import { getPlatform } from "@/platform";
import { getDisplayFreeResult, readCompletedSession, readLatestCompletedSession, type OfficialFreeResult } from "@/storage/goal-fit-session";
import { recoverLatestAssessment, retryPendingAssessmentSync } from "@/services/assessment-sync";
import { getActiveGoalFitVirtualPaymentState, invalidateGoalFitVirtualPaymentFlow, startManagedGoalFitVirtualPayment, subscribeGoalFitVirtualPaymentState, type GoalFitVirtualPaymentState } from "@/services/goal-fit-virtual-payment-controller";
const result=ref<OfficialFreeResult|null>(null),error=ref(""),assessmentId=ref(""),paymentState=ref<GoalFitVirtualPaymentState>(getActiveGoalFitVirtualPaymentState()),paymentMessage=ref(""),fullReport=ref<unknown|null>(null);let active=true,unsubscribe:(()=>void)|undefined;
function setPayment(state:GoalFitVirtualPaymentState){if(!active||(state.assessmentId&&state.assessmentId!==assessmentId.value))return;paymentState.value=state;paymentMessage.value=state.status==="pending"?"支付结果正在确认，请稍后返回本页查看":state.status==="cancelled"?"支付已取消":state.status==="closed"?"本次支付未完成，可以重新尝试":state.status==="review_required"?"支付状态需要进一步确认，请稍后重新进入查看":state.status==="unsupported"?"当前微信版本暂不支持支付，请升级微信后重试":state.status==="failed"?"支付暂时未能完成，请稍后再试":""}
async function load(id:string){let session=id?readCompletedSession(id):readLatestCompletedSession();if(!session)session=await recoverLatestAssessment();else void retryPendingAssessmentSync();const display=session?getDisplayFreeResult(session):null;if(!display){error.value="结果暂不可用，请重新开始测试。";return}assessmentId.value=session?.assessmentId??session?.id??"";result.value=display}
async function unlock(){const id=assessmentId.value;if(!id||paymentState.value.busy)return;const outcome=await startManagedGoalFitVirtualPayment({assessmentId:id});if(!active||id!==assessmentId.value)return;setPayment({status:outcome.status,assessmentId:id,busy:false,canRetry:true,...(outcome.safeCode?{safeCode:outcome.safeCode}:{})});if(outcome.status==="paid"&&outcome.report){fullReport.value=outcome.report;paymentMessage.value="完整报告已解锁"}}
onLoad(q=>{unsubscribe=subscribeGoalFitVirtualPaymentState(setPayment);void load(typeof q?.sessionId==="string"?q.sessionId:"")});onUnload(()=>{active=false;unsubscribe?.();if(assessmentId.value)invalidateGoalFitVirtualPaymentFlow({assessmentId:assessmentId.value})});function home(){uni.reLaunch({url:"/pages/index/index"})}function retry(){uni.reLaunch({url:"/pages/test-entry/index"})}
</script>
<template><view class="page"><view v-if="result" class="card"><text class="score">{{result.overallScore}} 分</text><text class="title">{{result.overallConclusion.title}}</text><text class="summary">{{result.overallConclusion.summary}}</text><text class="section">首要风险</text><text class="risk">{{result.primaryRisk.title}}</text><text class="summary">{{result.primaryRisk.description}}</text><view v-if="getPlatform()==='wechat_miniapp'"><button class="primary" :disabled="paymentState.busy" @click="unlock">{{paymentState.busy?'正在确认支付结果…':'解锁完整报告 ¥19.9'}}</button><text v-if="paymentMessage" class="summary">{{paymentMessage}}</text></view><view v-if="fullReport"><text class="section">完整报告已解锁</text><text class="summary">完整报告已由服务端加载。</text></view><button class="primary" @click="home">返回首页</button></view><view v-else class="card"><text class="title">结果暂不可用</text><text class="summary">{{error}}</text><button class="primary" @click="retry">重新测试</button></view></view></template>
<style scoped>.page{min-height:100vh;padding:48rpx 32rpx;box-sizing:border-box}.card{background:#fff;padding:36rpx;border-radius:24rpx}.score,.title,.summary,.section,.risk{display:block}.score{font-size:64rpx;font-weight:700;color:#4057d6}.title{font-size:40rpx;font-weight:700;margin:20rpx 0}.summary{line-height:1.65;color:#5f6675}.section{margin-top:36rpx;font-size:30rpx;font-weight:700}.risk{margin:16rpx 0;font-size:32rpx;font-weight:600}.primary{margin-top:32rpx;background:#4057d6;color:#fff}</style>
